SELECT DISTINCT ?father ?fatherLabel ?deathDate WHERE {
  {
    dbr:Princess_Adelheid_of_Anhalt-Bernburg-Schaumburg-Hoym dbo:father ?father .
  } UNION {
    dbr:Princess_Adelheid_of_Anhalt-Bernburg-Schaumburg-Hoym dbp:father ?father .
  } UNION {
    dbr:Princess_Adelheid_of_Anhalt-Bernburg-Schaumburg-Hoym dbo:parent ?father .
  } UNION {
    dbr:Princess_Adelheid_of_Anhalt-Bernburg-Schaumburg-Hoym dbp:parents ?father .
  }
  OPTIONAL { ?father dbo:deathDate ?deathDate . }
  OPTIONAL { ?father dbp:deathDate ?deathDate2 . }
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER (lang(?fatherLabel)='en') }
  BIND(COALESCE(?deathDate, ?deathDate2) AS ?deathDate)
} LIMIT 10

